1	//! Durable, forge-neutral release identity and digest primitives.
2	//!
3	//! This module deliberately owns only values and deterministic byte encodings.
4	//! Workspace discovery and release authorization remain in callisto-graph.
5	
6	use std::cmp::Ordering;
7	use std::collections::{BTreeMap, BTreeSet};
8	use std::fmt;
9	use std::io::Read;
10	use std::str::FromStr;
11	
12	use schemars::JsonSchema;
13	use serde::{Deserialize, Deserializer, Serialize, Serializer};
14	use sha2::{Digest, Sha256};
15	
16	use crate::{CommitSha, Ecosystem, PackageId, RegistryKey, Version};
