18	/// An exact, ecosystem-qualified package identity for durable release operations.
19	///
20	/// Unlike PackageId, this type has no bare form and therefore cannot use
21	/// wildcard matching across ecosystems.
22	#[derive(Clone, Debug, PartialEq, Eq, Hash, JsonSchema)]
23	#[schemars(with = "String")]
24	pub struct ReleasePackageId {
25	    ecosystem: Ecosystem,
26	    name: String,
27	}
28	
29	impl ReleasePackageId {
30	    /// Creates an exact release package identity.
31	    ///
32	    /// # Errors
33	    ///
34	    /// Returns ReleasePackageIdParseError when name is not valid in the
35	    /// existing package-identity grammar.
36	    pub fn new(ecosystem: Ecosystem, name: impl AsRef<str>) -> Result<Self, ReleasePackageIdParseError> {
37	        let name = name.as_ref();
38	        let raw = format!("{}/{}", ecosystem.prefix(), name);
39	        match PackageId::parse(&raw) {
40	            Ok(PackageId::Prefixed {
41	                ecosystem: parsed_ecosystem,
42	                name: parsed_name,
43	            }) if parsed_ecosystem == ecosystem && parsed_name == name => Ok(Self {
44	                ecosystem,
45	                name: parsed_name,
46	            }),
47	            _ => Err(ReleasePackageIdParseError::Malformed { raw }),
48	        }
49	    }
50	
51	    /// Parses the canonical 'ecosystem/name' release identity form.
52	    ///
53	    /// PackageId also accepts 'ecosystem:name'; release identities reject it
54	    /// so every durable encoding has exactly one spelling.
55	    pub fn parse(s: &str) -> Result<Self, ReleasePackageIdParseError> {
56	        if s.contains(':') {
57	            return Err(ReleasePackageIdParseError::NonCanonical { raw: s.to_string() });
58	        }
59	        let (prefix, name) = s
60	            .split_once('/')
61	            .ok_or_else(|| ReleasePackageIdParseError::MissingEcosystem { raw: s.to_string() })?;
62	        let ecosystem = Ecosystem::from_prefix(prefix)
63	            .ok_or_else(|| ReleasePackageIdParseError::UnknownEcosystem { raw: s.to_string() })?;
64	        let id = Self::new(ecosystem, name)?;
65	        if id.to_string() != s {
66	            return Err(ReleasePackageIdParseError::NonCanonical { raw: s.to_string() });
67	        }
68	        Ok(id)
69	    }
70	
71	    /// Returns the exact ecosystem.
72	    pub fn ecosystem(&self) -> Ecosystem {
73	        self.ecosystem
74	    }
75	
76	    /// Returns the package name without the ecosystem prefix.
77	    pub fn name(&self) -> &str {
78	        &self.name
79	    }
80	}
81	
82	impl fmt::Display for ReleasePackageId {
83	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
84	        write!(f, "{}/{}", self.ecosystem.prefix(), self.name)
85	    }
86	}
