141	/// An exact `owner/repo` GitHub repository identity.
142	///
143	/// Replaces three previously independent, inconsistent ad hoc validations of
144	/// the same concept (a bare `split_once('/')` check with no character-class
145	/// restriction, a stricter ASCII-alphanumeric-plus-`-_.` check, and an
146	/// entirely unvalidated `format!("{owner}/{repository}")`); every caller now
147	/// parses through this single charset rule instead.
148	#[derive(Clone, Debug, PartialEq, Eq, Hash, JsonSchema)]
149	#[schemars(with = "String")]
150	pub struct GitHubRepository {
151	    owner: String,
152	    repo: String,
153	}
154	
155	impl GitHubRepository {
156	    /// Parses an exact `owner/repo` GitHub repository identity.
157	    ///
158	    /// Both `owner` and `repo` must be non-empty, ASCII alphanumeric plus
159	    /// `-`, `_`, and `.`, and must not start or end with `-`. This is
160	    /// deliberately one charset rule applied uniformly to both parts,
161	    /// matching GitHub's own allowed repository-name charset closely enough
162	    /// to reject the unsafe inputs that matter (for example, embedded
163	    /// whitespace) without re-implementing GitHub's full, occasionally
164	    /// stricter, username rules.
165	    pub fn parse(s: &str) -> Result<Self, GitHubRepositoryParseError> {
166	        let Some((owner, repo)) = s.split_once('/') else {
167	            return Err(GitHubRepositoryParseError::MissingSeparator { raw: s.to_string() });
168	        };
169	        if repo.contains('/') {
170	            return Err(GitHubRepositoryParseError::TooManyParts { raw: s.to_string() });
171	        }
172	        if !is_valid_github_repository_part(owner) {
173	            return Err(GitHubRepositoryParseError::InvalidOwner { raw: s.to_string() });
174	        }
175	        if !is_valid_github_repository_part(repo) {
176	            return Err(GitHubRepositoryParseError::InvalidRepo { raw: s.to_string() });
177	        }
178	        Ok(Self {
179	            owner: owner.to_string(),
180	            repo: repo.to_string(),
181	        })
182	    }
183	
184	    /// Returns the owner component.
185	    pub fn owner(&self) -> &str {
186	        &self.owner
187	    }
188	
189	    /// Returns the repository-name component.
190	    pub fn repo(&self) -> &str {
191	        &self.repo
192	    }
193	
194	    /// Renders the canonical `owner/repo` slug, for example for `gh --repo`.
195	    pub fn as_slug(&self) -> String {
196	        format!("{}/{}", self.owner, self.repo)
197	    }
198	}
199	
200	impl fmt::Display for GitHubRepository {
201	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
202	        write!(f, "{}/{}", self.owner, self.repo)
203	    }
204	}
