244	
245	fn is_valid_github_repository_part(part: &str) -> bool {
246	    !part.is_empty()
247	        && !part.starts_with('-')
248	        && !part.ends_with('-')
249	        && part
250	            .bytes()
251	            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_' | b'.'))
252	}
