254	/// Errors produced while parsing a [`GitHubRepository`].
255	#[derive(Clone, Debug, PartialEq, Eq, thiserror::Error)]
256	#[non_exhaustive]
257	pub enum GitHubRepositoryParseError {
258	    #[error("GitHub repository `{raw}` must be in owner/repo form")]
259	    MissingSeparator { raw: String },
260	    #[error("GitHub repository `{raw}` has more than one `/`")]
261	    TooManyParts { raw: String },
262	    #[error("GitHub repository `{raw}` has an invalid owner")]
263	    InvalidOwner { raw: String },
264	    #[error("GitHub repository `{raw}` has an invalid repository name")]
265	    InvalidRepo { raw: String },
266	}
