268	macro_rules! release_digest {
269	    ($name:ident, $description:literal) => {
270	        #[doc = $description]
271	        #[derive(Clone, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, JsonSchema)]
272	        #[schemars(with = "String")]
273	        pub struct $name(String);
274	
275	        impl $name {
276	            /// Parses a lowercase hexadecimal SHA-256 digest.
277	            pub fn parse(raw: &str) -> Result<Self, DigestParseError> {
278	                if raw.len() != 64
279	                    || !raw
280	                        .bytes()
281	                        .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte))
282	                {
283	                    return Err(DigestParseError {
284	                        digest_kind: stringify!($name),
285	                        raw: raw.to_string(),
286	                    });
287	                }
288	                Ok(Self(raw.to_string()))
289	            }
290	
291	            /// Returns the canonical lowercase hexadecimal digest.
292	            pub fn as_str(&self) -> &str {
293	                &self.0
294	            }
295	
296	            fn from_sha256(bytes: impl AsRef<[u8]>) -> Self {
297	                let rendered = format!("{:x}", Sha256::digest(bytes.as_ref()));
298	                Self(rendered)
299	            }
300	        }
301	
302	        impl fmt::Display for $name {
303	            fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
304	                f.write_str(&self.0)
305	            }
306	        }
307	
308	        impl Serialize for $name {
309	            fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
310	            where
311	                S: Serializer,
312	            {
313	                serializer.serialize_str(&self.0)
314	            }
315	        }
316	
317	        impl<'de> Deserialize<'de> for $name {
318	            fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
319	            where
320	                D: Deserializer<'de>,
321	            {
322	                let raw = String::deserialize(deserializer)?;
323	                Self::parse(&raw).map_err(serde::de::Error::custom)
324	            }
325	        }
326	    };
327	}
