330	release_digest!(DecisionDigest, "SHA-256 over a release-decision transcript.");
331	release_digest!(SemanticInputDigest, "SHA-256 over a semantic-input transcript.");
332	release_digest!(IntentDigest, "SHA-256 over a release-intent transcript.");
