338	/// Error returned when a durable digest is not canonical lowercase SHA-256.
339	#[derive(Clone, Debug, PartialEq, Eq, thiserror::Error)]
340	#[error("{digest_kind} must be exactly 64 lowercase hexadecimal characters, got {raw}")]
341	pub struct DigestParseError {
342	    digest_kind: &'static str,
343	    raw: String,
344	}
345	
346	impl ArtifactDigest {
347	    /// Hashes the exact artifact bytes without normalization.
348	    pub fn from_bytes(bytes: impl AsRef<[u8]>) -> Self {
349	        Self::from_sha256(bytes)
350	    }
351	
352	    /// Streams exact artifact bytes into SHA-256 without retaining the full
353	    /// asset in memory. Release artifacts can be substantially larger than
354	    /// manifests, so executor verification must use this path.
355	    pub fn from_reader(mut reader: impl Read) -> std::io::Result<(Self, u64)> {
356	        let mut hasher = Sha256::new();
357	        let mut length = 0_u64;
358	        let mut buffer = [0_u8; 64 * 1024];
359	        loop {
360	            let read = reader.read(&mut buffer)?;
361	            if read == 0 {
362	                break;
363	            }
364	            hasher.update(&buffer[..read]);
365	            length = length.checked_add(read as u64).ok_or_else(|| {
366	                std::io::Error::new(std::io::ErrorKind::InvalidData, "artifact exceeds supported length")
367	            })?;
368	        }
369	        Ok((Self(format!("{:x}", hasher.finalize())), length))
370	    }
371	}
