380	/// The closed set of facts that can include a package in a durable release.
381	///
382	/// This is intentionally a model value: graph derives it, but every later
383	/// process can validate the exact approved roster without importing graph.
384	#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord, Serialize, Deserialize, JsonSchema)]
385	#[serde(
386	    rename_all = "camelCase",
387	    rename_all_fields = "camelCase",
