393	    Changeset,
394	    Inference,
395	    ExplicitSelection,
396	    LinkedGroup { group_id: String },
397	    FixedGroup { group_id: String },
398	    Cascade { from: ReleasePackageId, edge_kind: String },
399	    PreReleasePolicy { policy_id: String },
