411	/// Credential-free, deterministic release authority derived by callisto-graph.
412	#[derive(Clone, Debug, PartialEq, Eq, Serialize, JsonSchema)]
413	#[serde(rename_all = "camelCase", deny_unknown_fields)]
414	pub struct ReleaseDecisionV1 {
415	    pub schema_version: u8,
416	    pub entries: Vec<ReleaseDecisionEntry>,
417	    pub digest: DecisionDigest,
