420	#[derive(Deserialize)]
421	#[serde(rename_all = "camelCase", deny_unknown_fields)]
422	struct ReleaseDecisionV1Wire {
423	    schema_version: u8,
424	    entries: Vec<ReleaseDecisionEntry>,
425	    digest: DecisionDigest,
426	}
