428	impl<'de> Deserialize<'de> for ReleaseDecisionV1 {
429	    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
430	    where
431	        D: Deserializer<'de>,
432	    {
433	        let wire = ReleaseDecisionV1Wire::deserialize(deserializer)?;
434	        if wire.schema_version != Self::SCHEMA_VERSION {
435	            return Err(serde::de::Error::custom("unsupported release decision schema version"));
436	        }
437	        let decision = Self::new(wire.entries).map_err(serde::de::Error::custom)?;
438	        if decision.digest != wire.digest {
439	            return Err(serde::de::Error::custom(
440	                "release decision digest does not match canonical content",
441	            ));
442	        }
443	        Ok(decision)
444	    }
445	}
446	
447	impl ReleaseDecisionV1 {
448	    pub const SCHEMA_VERSION: u8 = 1;
449	
450	    /// Creates a canonical decision or rejects an ambiguous release roster.
451	    #[allow(clippy::result_large_err)]
452	    pub fn new(mut entries: Vec<ReleaseDecisionEntry>) -> Result<Self, ReleaseDecisionError> {
453	        if entries.is_empty() {
454	            return Err(ReleaseDecisionError::EmptyRoster);
455	        }
456	        for entry in &mut entries {
457	            entry.reasons.sort();
458	            entry.reasons.dedup();
459	            if entry.reasons.is_empty() {
460	                return Err(ReleaseDecisionError::MissingReason {
461	                    package: entry.package.clone(),
462	                });
463	            }
464	        }
465	        entries.sort_by(|left, right| left.package.cmp(&right.package));
466	        if entries.windows(2).any(|pair| pair[0].package == pair[1].package) {
467	            return Err(ReleaseDecisionError::DuplicatePackage);
468	        }
469	
470	        // A fixed or linked group always converges every member to one
471	        // shared target version -- `solve_cascade` guarantees this when a
472	        // decision is derived from a version plan. Entries tag their own
473	        // group membership via `FixedGroup`/`LinkedGroup` reasons, so this
474	        // invariant is checkable from the decision's own content alone, with
475	        // no `GroupTable`/workspace-config access needed. Rejecting a
476	        // violation here means it also applies to a decision deserialized
477	        // from a committed release-decision file (`Deserialize` calls
478	        // `new()`), not just one freshly derived from a plan.
479	        let mut group_targets: BTreeMap<&str, &Version> = BTreeMap::new();
480	        for entry in &entries {
481	            for reason in &entry.reasons {
482	                let group_id = match reason {
483	                    ReleaseInclusionReason::FixedGroup { group_id }
484	                    | ReleaseInclusionReason::LinkedGroup { group_id } => group_id.as_str(),
485	                    _ => continue,
486	                };
487	                match group_targets.get(group_id) {
488	                    Some(existing) if **existing != entry.target_version => {
489	                        return Err(ReleaseDecisionError::DivergentGroupTarget {
490	                            group_id: group_id.to_string(),
491	                            left: (*existing).clone(),
492	                            right: entry.target_version.clone(),
493	                        });
494	                    }
495	                    _ => {
496	                        group_targets.insert(group_id, &entry.target_version);
497	                    }
498	                }
499	            }
500	        }
501	
502	        let digest = decision_digest(&entries);
503	        Ok(Self {
504	            schema_version: Self::SCHEMA_VERSION,
505	            entries,
506	            digest,
507	        })
508	    }
509	}
510	
511	fn decision_digest(entries: &[ReleaseDecisionEntry]) -> DecisionDigest {
512	    let mut transcript = CanonicalTranscript::decision_v1();
513	    for entry in entries {
514	        transcript.push_str("package", &entry.package.to_string());
515	        transcript.push_str("target-version", entry.target_version.render());
516	        for reason in &entry.reasons {
517	            transcript.push_str(
518	                "reason",
519	                &serde_json::to_string(reason).expect("closed reason serializes"),
520	            );
521	        }
522	    }
523	    DecisionDigest::from_transcript(&transcript)
524	}
