531	    EmptyRoster,
532	    #[error("release decision repeats a package")]
533	    DuplicatePackage,
534	    #[error("release decision entry for {package} has no inclusion reason")]
535	    MissingReason { package: ReleasePackageId },
536	    #[error("release decision claims divergent target versions for group `{group_id}`: {left} vs {right}")]
537	    DivergentGroupTarget {
538	        group_id: String,
539	        left: Version,
540	        right: Version,
541	    },
542	}
