558	impl RegistryBindingDigest {
559	    /// Hashes a graph-normalized registry binding without retaining its source
560	    /// endpoint in a durable model value.
561	    ///
562	    /// The caller is responsible for URL parsing, rejecting credentials and
563	    /// query/fragment data, and producing a canonical binding before calling
564	    /// this method. Only this digest is retained.
565	    pub fn from_normalized_binding(bytes: impl AsRef<[u8]>) -> Self {
566	        let mut transcript = CanonicalTranscript::registry_binding_v1();
567	        transcript.push_bytes("binding", bytes);
568	        Self::from_sha256(transcript.as_bytes())
569	    }
570	}
