572	/// Deterministic length-prefixed bytes for a durable release digest.
573	///
574	/// The transcript starts with a fixed protocol marker, a one-byte schema
575	/// version, and a length-prefixed domain. Each appended field is a
576	/// length-prefixed UTF-8 tag followed by a length-prefixed byte value. Domain
577	/// types own ordering of fields; this primitive preserves that order exactly.
578	#[derive(Clone, Debug, PartialEq, Eq)]
579	pub struct CanonicalTranscript {
580	    bytes: Vec<u8>,
581	}
582	
583	impl CanonicalTranscript {
584	    const MARKER: &'static [u8] = b"callisto-release-transcript";
585	    const VERSION: u8 = 1;
586	
587	    /// Starts the v1 transcript used for semantic input snapshots.
588	    pub fn semantic_input_v1() -> Self {
589	        Self::v1(b"semantic-input")
590	    }
591	
592	    /// Starts the v1 transcript used for release decisions.
593	    pub fn decision_v1() -> Self {
594	        Self::v1(b"release-decision")
595	    }
596	
597	    /// Starts the v1 transcript used for release intents.
598	    pub fn intent_v1() -> Self {
599	        Self::v1(b"release-intent")
600	    }
601	
602	    /// Starts the v1 transcript used for normalized registry bindings.
603	    fn registry_binding_v1() -> Self {
604	        Self::v1(b"registry-binding")
605	    }
606	
607	    fn v1(domain: &[u8]) -> Self {
608	        let mut bytes = Vec::with_capacity(Self::MARKER.len() + domain.len() + 16);
609	        Self::push_length_prefixed(&mut bytes, Self::MARKER);
610	        bytes.push(Self::VERSION);
611	        Self::push_length_prefixed(&mut bytes, domain);
612	        Self { bytes }
613	    }
614	
615	    /// Appends one named UTF-8 field.
616	    pub fn push_str(&mut self, tag: &str, value: &str) {
617	        self.push_bytes(tag, value.as_bytes());
618	    }
619	
620	    /// Appends one named byte field.
