206	    pub const SCHEMA_VERSION: u8 = 2;
207	
208	    /// Derives the only permitted action from fresh workspace and forge facts.
209	    pub fn derive(
210	        has_pending_changesets: bool,
211	        config: &ReleasePrConfigV1,
212	        snapshot: &ReleasePrSnapshotV2,
213	    ) -> Result<Self, ReleasePrDecisionError> {
214	        if snapshot.repository != config.repository || snapshot.base_branch != config.base_branch {
215	            return Err(ReleasePrDecisionError::SnapshotIdentityMismatch);
216	        }
217	
218	        let staging_branch = config.staging_branch();
219	        let mut eligible = Vec::new();
220	        for pr in &snapshot.open_pull_requests {
221	            if pr.head_branch == staging_branch {
222	                return Err(ReleasePrDecisionError::StagingBranchPullRequest { number: pr.number });
223	            }
224	            let shape = managed_branch_shape(&config.release_branch, &pr.head_branch)?;
225	            if shape.is_some() {
226	                if pr.head_repository != config.repository {
227	                    return Err(ReleasePrDecisionError::ForeignManagedPullRequest {
228	                        number: pr.number,
229	                        repository: pr.head_repository.clone(),
230	                    });
231	                }
232	                eligible.push(pr);
233	            }
234	        }
235	        if eligible.len() > 1 {
236	            return Err(ReleasePrDecisionError::AmbiguousManagedPullRequests { count: eligible.len() });
237	        }
238	
239	        let action = if !has_pending_changesets {
240	            ReleasePrActionV2::Noop {
241	                reason: ReleasePrNoopReasonV1::NoPendingChangesets,
242	            }
243	        } else if let Some(pr) = eligible.first() {
244	            ReleasePrActionV2::Update {
245	                pull_request_number: pr.number,
246	                branch: pr.head_branch.clone(),
247	                expected_head_commit: pr.head_commit.clone(),
248	                staging_branch: staging_branch.clone(),
249	            }
250	        } else {
251	            ReleasePrActionV2::Create {
252	                branch: config.release_branch.clone(),
253	                staging_branch,
254	            }
255	        };
256	        Ok(Self {
257	            schema_version: Self::SCHEMA_VERSION,
258	            config: config.clone(),
259	            snapshot: snapshot.clone(),
260	            action,
261	        })
262	    }
263	
264	    /// Rejects any post-decision forge state change before the executor mutates.
265	    pub fn verify_snapshot(&self, observed: &ReleasePrSnapshotV2) -> Result<(), ReleasePrDecisionError> {
266	        if observed != &self.snapshot {
267	            return Err(ReleasePrDecisionError::SnapshotChanged);
268	        }
269	        Ok(())
270	    }
271	}
