392	fn validate_branch(kind: &'static str, branch: &str) -> Result<(), ReleasePrDecisionError> {
393	    let valid = !branch.is_empty()
394	        && !branch.starts_with('-')
395	        && !branch.starts_with('/')
396	        && !branch.ends_with('/')
397	        && !branch.contains("//")
398	        && !branch.contains("..")
399	        && !branch.contains("@{")
400	        && branch != "@"
401	        && branch
402	            .split('/')
403	            .all(|part| !part.starts_with('.') && !part.ends_with(".lock"))
404	        && branch.chars().all(|ch| {
405	            !ch.is_ascii_control() && !ch.is_whitespace() && !matches!(ch, '~' | '^' | ':' | '?' | '*' | '[' | '\\')
406	        });
407	    if valid {
408	        Ok(())
409	    } else {
410	        Err(ReleasePrDecisionError::InvalidBranch {
411	            kind,
412	            branch: branch.to_string(),
413	        })
414	    }
415	}
