417	fn managed_branch_shape(canonical: &str, branch: &str) -> Result<Option<()>, ReleasePrDecisionError> {
418	    if branch == canonical {
419	        return Ok(Some(()));
420	    }
421	    let Some(suffix) = branch.strip_prefix(&format!("{canonical}--")) else {
422	        return Ok(None);
423	    };
424	    if suffix.len() == 40
425	        && suffix
426	            .bytes()
427	            .all(|byte| byte.is_ascii_digit() || matches!(byte, b'a'..=b'f'))
428	    {
429	        Ok(Some(()))
430	    } else {
431	        Err(ReleasePrDecisionError::MalformedManagedBranch {
432	            branch: branch.to_string(),
433	        })
434	    }
435	}
